<?php
declare(strict_types=1);require_once __DIR__.'/../config/conexion.php';require_once __DIR__.'/../includes/seguridad.php';require_once __DIR__.'/../includes/permisos.php';
require_role(['administrador','coordinador_mg','auxiliar_mg']);requerir_permiso('mg.reportes.ver');
$cohorte=(int)($_GET['id_cohorte']??0);$modalidad=(int)($_GET['id_modalidad']??0);$etapa=trim($_GET['etapa']??'');$estado=trim($_GET['estado']??'');$where=[];$params=[];if($cohorte){$where[]='x.id_cohorte=?';$params[]=$cohorte;}if($modalidad){$where[]='x.id_modalidad=?';$params[]=$modalidad;}if($etapa){$where[]='x.etapa_actual=?';$params[]=$etapa;}if($estado){$where[]='x.estado=?';$params[]=$estado;}$w=$where?' WHERE '.implode(' AND ',$where):'';
$tablaInformes=(bool)$pdo->query("SELECT COUNT(*) FROM information_schema.tables WHERE table_schema=DATABASE() AND table_name='informes_avance'")->fetchColumn();$avanceSql=$tablaInformes?'(SELECT MAX(i.porcentaje_avance) FROM informes_avance i WHERE i.id_expediente=x.id_expediente)':'NULL';$sql="SELECT x.id_expediente,e.registro_universitario,u.nombre,u.apellido,m.nombre modalidad_nombre,c.nombre cohorte_nombre,x.etapa_actual,x.estado,x.fecha_inicio,(SELECT a.id_tutor FROM asignaciones_tutor a WHERE a.id_expediente=x.id_expediente AND a.estado='vigente' LIMIT 1) id_tutor,{$avanceSql} AS ultimo_avance FROM expedientes_mg x JOIN estudiantes e ON e.id_estudiante=x.id_estudiante JOIN usuarios u ON u.id_usuario=e.id_usuario JOIN modalidades_grado m ON m.id_modalidad=x.id_modalidad JOIN cohortes_mg c ON c.id_cohorte=x.id_cohorte{$w} ORDER BY c.fecha_inicio DESC,u.apellido,u.nombre";$s=$pdo->prepare($sql);$s->execute($params);$filas=$s->fetchAll();
if(($_GET['formato']??'')==='csv'){header('Content-Type:text/csv; charset=UTF-8');header('Content-Disposition: attachment; filename="reporte_mg_cohorte.csv"');echo "\xEF\xBB\xBF";$out=fopen('php://output','w');fputcsv($out,['Estudiante','Registro','Modalidad','Cohorte','Etapa','Estado','Inicio','Avance'], ';');foreach($filas as $r){$vals=[$r['apellido'].', '.$r['nombre'],$r['registro_universitario'],$r['modalidad_nombre'],$r['cohorte_nombre'],$r['etapa_actual'],$r['estado'],$r['fecha_inicio'],$r['ultimo_avance']??''];$vals=array_map(fn($v)=>preg_match('/^[=+\-@]/',(string)$v)?"'".$v:$v,$vals);fputcsv($out,$vals,';');}fclose($out);exit;}
